-- Generated by generar_seed_sql.py: demo data for every table still empty after 01-05.
-- Run AFTER 01_schema.sql .. 04_seed_loads_v2.sql (05_security_rls.sql may run before or after;
-- the Supabase SQL editor runs as postgres and bypasses RLS). Everything goes through the schema's
-- triggers and state machine (no trigger is disabled), in ONE transaction:
--   1. V1 validation findings (reference oracle) -> V1 loads move to CUARENTENA / PENDIENTE_APROBACION
--   2. V2 loads approved (V2 has no findings)
--   3. IC documents of V2 derived from vMappedLine, issued (mirror receivable/payable), accepted
--   4. Reference consolidation run of V2 (reconciliation, eliminations, consolidated, lineage)
--   5. Fix of the inverted MXN rate (E01 / V08, own audit reason), corrected-V1 reference run, V1 -> V2 variance bridge
--   6. IC documents with an eliminable reconciliation -> CONCILIADA
begin;

set local app.change_reason = 'Seed 06 demo data';



-- 2. V1 findings. loadId is resolved from registro: a lineId, or a file stem ('presupuesto_GT2', 'balance_GT1 2027-12'
--    -> first token + '_V1'); anything else (TP-MGMT, rate table) is a cross-load finding with loadId null.
insert into "validationFinding" ("loadId", "scenarioId", "ruleCode", "severityCode", "companyCode", "recordRef", "message", "foundValue", "expectedValue", "impactUsd")
select coalesce(l."loadId", d."loadId"), 'PPTO_V1', v.rule, v.sev, v.company, v.ref, v.msg, v.found, v.expected, v.impact
from (values
  ('V14'::text, 'A'::text, 'US2→MX2'::text, 'TP-MGMT'::text, 'Fee de gestión US2→MX2 = 8.0% de ventas de MX2; política 2%–5%'::text, '8.0%'::text, '2%–5%'::text, 53999.99::numeric),
  ('V18'::text, 'A'::text, 'GT2'::text, 'presupuesto_GT2_V1.csv#fila87'::text, 'IC-F4-2027-12: emisor US1 lo registra en 2027-12, receptor GT2 en 2027-11 (corte)'::text, '2027-11'::text, '2027-12'::text, 20000.0::numeric),
