  ('V04'::text, 'B'::text, 'US1'::text, 'presupuesto_US1_V1.csv#fila86'::text, 'Línea duplicada (4000 2027-04)'::text, null::text, null::text, 300000.0::numeric),
  ('V05'::text, 'B'::text, 'GT2'::text, 'presupuesto_GT2'::text, 'Periodo 2027-03 sin ninguna línea'::text, 'falta 2027-03'::text, '12 periodos'::text, 128205.13::numeric),
  ('V02'::text, 'B'::text, 'MX1'::text, 'presupuesto_MX1_V1.csv#fila14'::text, 'Moneda declarada USD ≠ moneda funcional MXN'::text, 'USD'::text, 'MXN'::text, 56666.67::numeric),
  ('V12'::text, 'B'::text, 'MX2/MX1'::text, 'presupuesto_MX2_V1.csv#fila30'::text, 'IC-F3-2027-06: solo existe la pata del receptor (compra); falta el espejo en MX1'::text, null::text, null::text, 50000.0::numeric),
