  ('V12'::text, 'B'::text, 'US2/GT2'::text, 'presupuesto_US2_V1.csv#fila20'::text, 'IC-F5b-2027-03: solo existe la pata del emisor (venta); falta el espejo en GT2'::text, null::text, null::text, 3000.0::numeric)
) as v(rule, sev, company, ref, msg, found, expected, impact)
left join "dataLoadLine" l on l."lineId" = v.ref
left join "dataLoad" d on d."scenarioId" = 'PPTO_V1' and l."lineId" is null
                      and starts_with(d."fileName", split_part(v.ref, ' ', 1) || '_V1');

-- 3. V1 loads: blocking findings -> CUARENTENA, only warnings -> PENDIENTE_APROBACION, the rest stay RECIBIDA.
update "dataLoad" d
   set "statusCode" = case when f."blocking" then 'CUARENTENA' else 'PENDIENTE_APROBACION' end
  from (select f."loadId", bool_or(s."isBlocking") as "blocking"
          from "validationFinding" f join "severity" s using ("severityCode")
         where f."loadId" is not null group by f."loadId") f
 where d."loadId" = f."loadId" and d."scenarioId" = 'PPTO_V1';

-- 4. V2 has zero findings: approve every load.
update "dataLoad" set "statusCode" = 'APROBADA' where "scenarioId" = 'PPTO_V2';

-- 5. IC documents of V2, derived from the mapped lines: issuer leg = IC income/asset line; receiver = icPartnerCode.
--    Type = the one whose issuer P&L account (preferred) or balance account matches the group account (NC excluded);
--    when a document has both legs the P&L one wins. Only documents without a P&L leg use the balance leg (loan on 1600).
insert into "icDocument" ("icDocumentId", "scenarioId", "icDocumentTypeCode", "issuerCompanyId", "receiverCompanyId",
                          "transactionCurrencyCode", "transactionAmount", "periodCode", "transferPricingPolicyId", "statusCode")
select x."icDocumentId", 'PPTO_V2', x."typeCode", x."companyCode", x."icPartnerCode", x."transactionCurrencyCode",
       x."transactionAmount", x."periodCode", p."policyId", 'EMITIDA'
from (
  select distinct on (m."icDocumentId") m."icDocumentId", ty."icDocumentTypeCode" as "typeCode", m."companyCode", m."icPartnerCode",
         m."transactionCurrencyCode", m."transactionAmount", m."periodCode"
    from "vMappedLine" m
    join "icDocumentType" ty on ty."icDocumentTypeCode" <> 'NC'
     and ((m."financialStatementCode" = 'PYG'     and ty."issuerPlAccountId" = m."groupAccountId")
       or (m."financialStatementCode" = 'BALANCE' and ty."issuerBsAccountId" = m."groupAccountId"))
   where m."scenarioId" = 'PPTO_V2' and m."isIntercompany" and m."accountTypeCode" in ('ING', 'ACT') and m."icDocumentId" is not null
   order by m."icDocumentId", (m."financialStatementCode" = 'PYG') desc, ty."icDocumentTypeCode"
) x
left join "transferPricingPolicy" p on p."icDocumentTypeCode" = x."typeCode";

-- Accept them all (receiver side); the mirror trigger already created the receivable/payable legs.
do $$ begin perform "fnAcceptIcDocument"("icDocumentId", "version") from "icDocument" where "scenarioId" = 'PPTO_V2'; end $$;

-- 6. Reference consolidation run of V2 (snapshots parameters and rates hash by trigger).
insert into "consolidationRun" ("scenarioId", "notes") values ('PPTO_V2', 'Reference run loaded from oracle v2 results');

insert into "consolidationRunLoad" ("runId", "loadId")
select (select "runId" from "consolidationRun" where "notes" = 'Reference run loaded from oracle v2 results'), "loadId" from "dataLoad" where "scenarioId" = 'PPTO_V2' and "statusCode" = 'APROBADA';


