update "consolidationRun" set "lineageOk" = not exists (
  select 1 from "consolidatedBalance" c
   where c."runId" = (select "runId" from "consolidationRun" where "notes" = 'Reference run loaded from oracle v2 results')
     and abs(c."consolidatedUsd" - coalesce((select sum(l."contributionUsd") from "lineage" l
                                              where l."runId" = c."runId" and l."groupAccountId" = c."groupAccountId"), 0)) > 1)
 where "runId" = (select "runId" from "consolidationRun" where "notes" = 'Reference run loaded from oracle v2 results');

-- A. Fix the E01 inverted rate found by V08 (audited with its own reason). Must precede the V1 run (rates hash snapshot).
set local app.change_reason = 'Fix E01: inverted MXN PRESUPUESTO rate 2027-05 (finding V08)';
update "groupExchangeRate" set "rateToUsd" = 0.05555556 where "scenarioId" = 'PPTO_V1' and "periodCode" = '2027-05' and "currencyCode" = 'MXN' and "rateTypeCode" = 'PRESUPUESTO';
set local app.change_reason = 'Seed 06 demo data';

-- B. Corrected-V1 reference run. No consolidationRunLoad: the V1 loads in the DB are the erroneous ones and are not APROBADA.
