update "consolidationRun" set "lineageOk" = not exists (
  select 1 from "consolidatedBalance" c
   where c."runId" = (select "runId" from "consolidationRun" where "notes" = 'Reference run loaded from oracle v1 corrected results')
     and abs(c."consolidatedUsd" - coalesce((select sum(l."contributionUsd") from "lineage" l
                                              where l."runId" = c."runId" and l."groupAccountId" = c."groupAccountId"), 0)) > 1)
 where "runId" = (select "runId" from "consolidationRun" where "notes" = 'Reference run loaded from oracle v1 corrected results');

-- C. Variance bridge V1 (corrected) -> V2 from the oracle
insert into "varianceBridge" ("fromRunId", "toRunId", "notes")
select (select "runId" from "consolidationRun" where "notes" = 'Reference run loaded from oracle v1 corrected results'), (select "runId" from "consolidationRun" where "notes" = 'Reference run loaded from oracle v2 results'), 'PPTO_V1 (corrected) → PPTO_V2, loaded from oracle bridge';

insert into "varianceBridgeLine" ("bridgeId", "effectCode", "companyId", "groupAccountId", "periodCode", "salesDeltaUsd", "ebitDeltaUsd", "icDetailUsd")
select b."bridgeId", v.* from (select "bridgeId" from "varianceBridge" where "fromRunId" = (select "runId" from "consolidationRun" where "notes" = 'Reference run loaded from oracle v1 corrected results') and "toRunId" = (select "runId" from "consolidationRun" where "notes" = 'Reference run loaded from oracle v2 results')) b, (values
