insert into "varianceBridgeEva" ("bridgeId", "effectCode", "evaDeltaUsd")
select b."bridgeId", v.* from (select "bridgeId" from "varianceBridge" where "fromRunId" = (select "runId" from "consolidationRun" where "notes" = 'Reference run loaded from oracle v1 corrected results') and "toRunId" = (select "runId" from "consolidationRun" where "notes" = 'Reference run loaded from oracle v2 results')) b, (values
  ('EBIT_DESPUES_IMPUESTOS'::text, 36072.23::numeric),
  ('TASA_IMPUESTO'::text, -2084.06::numeric),
  ('WACC'::text, -149432.12::numeric),
  ('CAPITAL_INVERTIDO'::text, 20462.17::numeric))
as v(c0, c1);

-- Documents whose reconciliation allows elimination become CONCILIADA.
update "icDocument" d set "statusCode" = 'CONCILIADA'
 where d."scenarioId" = 'PPTO_V2' and d."statusCode" = 'ACEPTADA'
   and exists (select 1 from "icReconciliation" r join "status" s on s."domainCode" = 'RECONCILIATION' and s."statusCode" = r."statusCode"
                where r."runId" = (select "runId" from "consolidationRun" where "notes" = 'Reference run loaded from oracle v2 results') and r."icDocumentId" = d."icDocumentId" and s."allowsElimination");

